const {
  withAndroidManifest,
  withDangerousMod,
  withMainActivity,
  AndroidConfig,
} = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

/**
 * Declares an Android Direct Share target ("Sharing Shortcuts") so Gator can surface in the
 * PRIORITIZED row of the system share sheet — the "share straight to a person/conversation" band
 * above the generic app list — instead of only the lower all-apps list.
 *
 * Why a plugin: this project is managed — `android/` is gitignored and regenerated by `expo
 * prebuild` on every (EAS) build — so a hand-edited manifest / res file wouldn't survive. This
 * writes `res/xml/shortcuts.xml` with a <share-target>, points MainActivity at it via the
 * `android.app.shortcuts` meta-data, and declares the two generic Android share actions consumed
 * by the owned bounded `gator-share-intake` module.
 *
 * IMPORTANT — this is the DECLARATION half only. Android shows Direct Share results for a
 * <share-target> only once the app ALSO publishes matching dynamic shortcuts at runtime, tagged
 * with the SAME category. That half lives in the local native module `modules/gator-share-shortcuts`
 * (driven from `src/services/shortcuts/shareShortcuts.ts`); both category strings must stay
 * identical or Android surfaces nothing. The generic app-list entry comes from the SEND intent
 * filters installed below and keeps working regardless.
 */

// Kept in sync with app.config.ts `android.package`.
const PACKAGE = 'com.bluegreengatorapps.messages';
const MAIN_ACTIVITY = `${PACKAGE}.MainActivity`;
const SHARE_TARGET_CATEGORY = `${PACKAGE}.category.SHARE_TARGET`;
const ON_CREATE_CAPTURE =
  'expo.modules.gatorshareintake.GatorShareIntakeActivityBridge.captureOnCreate(this, intent, savedInstanceState)';
const ON_NEW_INTENT_CAPTURE =
  'expo.modules.gatorshareintake.GatorShareIntakeActivityBridge.captureOnNewIntent(this, intent)';
const CAPTURE_BEGIN =
  '// @generated begin gator-share-intake-capture - expo prebuild (DO NOT MODIFY)';
const CAPTURE_END = '// @generated end gator-share-intake-capture';

// `*/*` on purpose. Android only offers Direct Share targets for a mime type the <share-target>
// DECLARES, so listing only image/video/text meant a shared PDF (or audio, zip, vCard…) matched no
// share-target and the priority row came back EMPTY — even though the app's SEND intent filters
// accept `*/*` and the shortcuts were published correctly. It must stay a subset of those filters
// (see applyShareIntentManifestPolicy below, which declares `*/*`).
const SHORTCUTS_XML = `<?xml version="1.0" encoding="utf-8"?>
<shortcuts xmlns:android="http://schemas.android.com/apk/res/android">
  <share-target android:targetClass="${MAIN_ACTIVITY}">
    <data android:mimeType="*/*" />
    <category android:name="${SHARE_TARGET_CATEGORY}" />
  </share-target>
</shortcuts>
`;

/** Write res/xml/shortcuts.xml into the generated native project. */
function withShortcutsResource(config) {
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const xmlDir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'src',
        'main',
        'res',
        'xml',
      );
      fs.mkdirSync(xmlDir, { recursive: true });
      fs.writeFileSync(path.join(xmlDir, 'shortcuts.xml'), SHORTCUTS_XML);
      return cfg;
    },
  ]);
}

const INBOUND_SHARE_ACTIONS = ['android.intent.action.SEND', 'android.intent.action.SEND_MULTIPLE'];

function shareIntentFilter(action) {
  return {
    action: [{ $: { 'android:name': action } }],
    category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
    data: [{ $: { 'android:mimeType': '*/*' } }],
  };
}

/** Install the exact owned inbound-share declarations on MainActivity, idempotently. */
function applyShareIntentManifestPolicy(activity) {
  activity['meta-data'] = (activity['meta-data'] ?? []).filter(
    (entry) => entry.$?.['android:name'] !== 'android.app.shortcuts',
  );
  activity['meta-data'].push({
    $: { 'android:name': 'android.app.shortcuts', 'android:resource': '@xml/shortcuts' },
  });

  activity['intent-filter'] = (activity['intent-filter'] ?? []).filter((filter) => {
    const actions = (filter.action ?? []).map((entry) => entry.$?.['android:name']);
    return !actions.some((action) => INBOUND_SHARE_ACTIONS.includes(action));
  });
  activity['intent-filter'].push(...INBOUND_SHARE_ACTIONS.map(shareIntentFilter));
  return activity;
}

/** Point MainActivity (the LAUNCHER activity) at the shortcuts resource and owned intake. */
function withShareIntentManifest(config) {
  return withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    applyShareIntentManifestPolicy(activity);
    return cfg;
  });
}

function stripGeneratedCapture(source) {
  const escapedBegin = CAPTURE_BEGIN.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const escapedEnd = CAPTURE_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return source.replace(
    new RegExp(`^[ \\t]*${escapedBegin}\\r?\\n[\\s\\S]*?^[ \\t]*${escapedEnd}\\r?\\n?`, 'gm'),
    '',
  );
}

/** Put synchronous native capture before ReactActivity sees either launch intent. */
function applyMainActivityShareCapture(source) {
  let next = stripGeneratedCapture(source);
  const onCreate =
    /(override\s+fun\s+onCreate\s*\(\s*savedInstanceState:\s*Bundle\?\s*\)\s*\{\s*\n)/;
  if (!onCreate.test(next)) {
    throw new Error('withShareTargets could not find Kotlin MainActivity.onCreate');
  }
  next = next.replace(
    onCreate,
    `$1    ${CAPTURE_BEGIN}\n    ${ON_CREATE_CAPTURE}\n    ${CAPTURE_END}\n`,
  );

  const onNewIntent =
    /(override\s+fun\s+onNewIntent\s*\(\s*intent:\s*(?:android\.content\.)?Intent\s*\)\s*\{\s*\n)/;
  if (onNewIntent.test(next)) {
    return next.replace(
      onNewIntent,
      `$1    ${CAPTURE_BEGIN}\n    ${ON_NEW_INTENT_CAPTURE}\n    ${CAPTURE_END}\n`,
    );
  }

  const superCreate = next.indexOf('super.onCreate(');
  const onCreateEnd = superCreate < 0 ? -1 : next.indexOf('\n  }', superCreate);
  if (onCreateEnd < 0) {
    throw new Error('withShareTargets could not locate the end of Kotlin MainActivity.onCreate');
  }
  const insertion = `\n\n  override fun onNewIntent(intent: android.content.Intent) {\n    ${CAPTURE_BEGIN}\n    ${ON_NEW_INTENT_CAPTURE}\n    ${CAPTURE_END}\n    super.onNewIntent(intent)\n  }`;
  return `${next.slice(0, onCreateEnd + 4)}${insertion}${next.slice(onCreateEnd + 4)}`;
}

function withMainActivityShareCapture(config) {
  return withMainActivity(config, (cfg) => {
    if (cfg.modResults.language !== 'kt') {
      throw new Error('withShareTargets requires a Kotlin MainActivity');
    }
    cfg.modResults.contents = applyMainActivityShareCapture(cfg.modResults.contents);
    return cfg;
  });
}

module.exports = function withShareTargets(config) {
  return withMainActivityShareCapture(withShareIntentManifest(withShortcutsResource(config)));
};

module.exports.INBOUND_SHARE_ACTIONS = INBOUND_SHARE_ACTIONS;
module.exports.SHARE_TARGET_CATEGORY = SHARE_TARGET_CATEGORY;
module.exports.SHORTCUTS_XML = SHORTCUTS_XML;
module.exports.ON_CREATE_CAPTURE = ON_CREATE_CAPTURE;
module.exports.ON_NEW_INTENT_CAPTURE = ON_NEW_INTENT_CAPTURE;
module.exports.applyShareIntentManifestPolicy = applyShareIntentManifestPolicy;
module.exports.applyMainActivityShareCapture = applyMainActivityShareCapture;
